// Read/write interleaving decides how many layouts the engine runs.
const cards = document.querySelectorAll(".card");

// BAD: each iteration reads geometry after writing styles,
// forcing a synchronous layout per card.
for (const card of cards) {
  const h = card.offsetHeight;      // read: pending writes flush here
  card.style.height = h * 2 + "px"; // write: invalidates layout again
}

// GOOD: read all geometry first, then write all styles.
// The engine layouts once for the batch instead of once per card.
const heights = Array.from(cards, (card) => card.offsetHeight);
cards.forEach((card, i) => {
  card.style.height = heights[i] * 2 + "px";
});
